<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useManagementStore } from '../stores/management'
const store = useManagementStore(), form = ref({ studentId:'', courseId:'' }), selectedCourse = ref(''), message=ref(''), error=ref(''), busy=ref(false)
const roster = computed(() => selectedCourse.value ? store.enrollments.filter(e => e.course?._id === selectedCourse.value) : store.enrollments)
onMounted(async () => { try { await Promise.all([store.loadStudents(), store.loadCourses(), store.loadEnrollments()]) } catch(e) { error.value=e.message } })
watch(selectedCourse, async id => { try { await store.loadEnrollments(id) } catch(e) { error.value=e.message } })
async function submit() { message.value=''; error.value=''; busy.value=true; try { await store.addEnrollment({ ...form.value }); message.value='Student enrolled successfully.'; selectedCourse.value=form.value.courseId; form.value.studentId='' } catch(e) { error.value=e.message } finally { busy.value=false } }
async function remove(item) { if (!confirm('Remove this enrollment?')) return; try { await store.deleteEnrollment(item._id); message.value='Enrollment removed.' } catch(e) { error.value=e.message } }
</script>
<template><section class="page-heading"><div><div class="eyebrow">ACADEMICS / REGISTRATION</div><h1>Enrollment management</h1><p class="subtitle">Connect students to courses and view the roster for each course.</p></div><div class="heading-chip"><span class="chip-icon">⇄</span><span><strong>{{ store.enrollments.length }} enrollments</strong><small>ACTIVE RECORDS</small></span></div></section>
<div v-if="message" class="alert success" role="status">✓ {{ message }}</div><div v-if="error" class="alert error" role="alert">{{ error }}</div><div class="two-column enrollment-layout"><section class="panel form-panel"><div class="panel-heading"><div><span class="section-kicker">REGISTRATION</span><h2>Enroll a student</h2></div><span class="panel-icon">＋</span></div><form @submit.prevent="submit"><label>Select student<select v-model="form.studentId" required><option value="" disabled>Choose a student…</option><option v-for="s in store.students" :key="s._id" :value="s._id">{{ s.name }} ({{ s.studentId }})</option></select></label><label>Select course<select v-model="form.courseId" required><option value="" disabled>Choose a course…</option><option v-for="c in store.courses" :key="c._id" :value="c._id">{{ c.courseId }} — {{ c.courseName }}</option></select></label><button class="primary-button" :disabled="busy || !store.students.length || !store.courses.length">{{ busy ? 'Enrolling…' : 'Create enrollment' }} <span>→</span></button></form><p class="form-note">A student can only be enrolled in the same course once.</p><div v-if="!store.students.length || !store.courses.length" class="inline-note">Add at least one student and one course before creating an enrollment.</div></section>
<section class="panel list-panel"><div class="panel-heading"><div><span class="section-kicker">CLASS ROSTER</span><h2>Enrolled students</h2></div><span class="count-pill">{{ roster.length }} ENROLLED</span></div><label class="filter-label">View course<select v-model="selectedCourse"><option value="">All courses</option><option v-for="c in store.courses" :key="c._id" :value="c._id">{{ c.courseId }} — {{ c.courseName }}</option></select></label><div v-if="!roster.length" class="empty-state"><span class="empty-icon">⇄</span><strong>No enrollments found</strong><small>Select a course or create a new enrollment.</small></div><div v-else class="table-wrap"><table><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>COURSE</th><th></th></tr></thead><tbody><tr v-for="item in roster" :key="item._id"><td><div class="person-cell"><span class="avatar">{{ item.student?.name?.charAt(0)?.toUpperCase() || '?' }}</span><strong>{{ item.student?.name || 'Student unavailable' }}</strong></div></td><td class="mono">{{ item.student?.studentId || '—' }}</td><td><span class="course-tag">{{ item.course?.courseId || '—' }}</span></td><td><button class="icon-button danger-text" aria-label="Remove enrollment" @click="remove(item)">×</button></td></tr></tbody></table></div></section></div></template>
